rue, "landing_page_url": "https://doi.org/10.1007/s11948-025-00554-z", "pdf_url": "https://link.springer.com/content/pdf/10.1007/s11948-025-00554-z.pdf", "source": {"id": "https://openalex.org/S14881475", "display_name": "Science and Engineering Ethics", "issn_l": "1353-3452", "issn": ["1353-3452", "1471-5546"], "is_oa": true, "is_in_doaj": true, "is_core": true, "listed_in": ["anvur-class-a", "anvur-scientific", "cwts-core", "doaj", "dongbi-b", "doyens", "jufo-2", "ki-jl-1", "medline", "norway-1", "poland-70", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319900", "host_organization_name": "Springer Science+Business Media", "host_organization_lineage": ["https://openalex.org/P4310319900", "https://openalex.org/P4310319965"], "host_organization_lineage_names": ["Springer Science+Business Media", "Springer Nature"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Science and Engineering Ethics", "raw_type": "journal-article"}, "abstract": "With a plethora of different seemingly diverging expansions for use of Meaningful Human Control (MHC) in practice, this paper proposes an alignment for the operationalisation of MHC for autonomous systems by proposing operational principles for MHC and introducing a generic framework for its application. The increasing integration of autonomous systems in various domains emphasises a critical need to maintain human control to ensure responsible safety, accountability, and ethical operation of these systems. The concept of MHC offers an ideal concept for the design and evaluation of human control over autonomous systems, while considering human and technology capabilities. Through conceptual synthesis of existing literature and investigation across various domains and related concepts, principles for the operationalisation of MHC are set out to provide tangible guidelines for researchers and practitioners aiming to implement MHC in their systems. The proposed framework dissects generic components of systems and their subsystems aligned with different agents, stakeholders and processes at different levels of proximity to an autonomous technology. The framework is domain-agnostic, emphasizing the universal applicability of the MHC principles irrespective of the technological context, paving the way for safer and more responsible autonomous systems."}]", "excerpt_truncated": true, "source_sha256": "2f2f97be90823ba074a69037659762c99f6f41e9dbbad9dae6945b537a8f4536", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2607.00710", "doi:10.31674/mjmr.2026.v010i03.01", "doi:10.1007/s11948-025-00554-z", "doi:10.1007/s11948-025-00554-z.pdf", "openalex:W7167046160", "openalex:W7203789670", "arxiv:2607.00710"], "source_candidates": ["https://doi.org/10.48550/arxiv.2607.00710", "https://arxiv.org/pdf/2607.00710", "https://arxiv.org/abs/2607.00710", "https://doi.org/10.31674/mjmr.2026.v010i03.01", "https://doi.org/10.1007/s11948-025-00554-z", "https://link.springer.com/content/pdf/10.1007/s11948-025-00554-z.pdf"], "source_candidate_identities": {}}
